//! The logos and the palette, generated by `art/scripts/afterfetch_art.py` (run `make art`).
//!
//! Every logo is an `.afl` blob (`docs/logo-format.md`); this crate holds the bytes and an index of where each section
//! starts, and the core's decoder reads them. Nothing here allocates or can panic, so it builds for every target.

#![cfg_attr(not(test), no_std)]

#[rustfmt::skip]
#[path = "generated/index.rs"]
mod index;
#[rustfmt::skip]
#[path = "generated/palette.rs"]
mod palette;

pub use index::{DEFAULTS, LOGOS};
pub use palette::{ARCH_ACCENTS, TONES};

/// The logo used when nothing more specific applies.
pub const FALLBACK_LOGO: &str = "afterglow";

/// How strongly a tone shows in mono: bold, plain or faint on Unix, the intensity bit on DOS and MDA.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mono {
	Bright,
	Normal,
	Dim,
}

/// One colour of the palette and what it shows at each depth. An absent `console16` (and so `ansi16`) or `mono` means
/// the tone is drawn as transparent at that depth.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Tone {
	/// 1 to 15; 0 is transparent in a blob. Never reused.
	pub id: u8,
	pub name: &'static str,
	/// The tone's letter in `art/ascii/*.txt` tone rows.
	pub letter: u8,
	/// The design colour, shown at truecolour.
	pub rgb: [u8; 3],
	/// The xterm-256 index, 16 to 255.
	pub xterm256: u8,
	/// The console attribute index at 16 colours (Win32 consoles, DOS, Windows 3.1).
	pub console16: Option<u8>,
	/// The SGR index at 16 colours: `console16` with bits 0 and 2 swapped.
	pub ansi16: Option<u8>,
	pub mono: Option<Mono>,
}

/// Where a section's payload sits in a blob: `offset` is the first payload byte, after the three-byte section header.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Section {
	pub offset: u16,
	pub len: u16,
}

/// One generated logo. The numbers are what the blob's header and sections say, so a reader can size its buffers and find
/// a section without decoding the others; the reader still validates the blob.
#[derive(Clone, Copy, Debug)]
pub struct LogoEntry {
	pub name: &'static str,
	/// The systems the logo stands for, for the `--logo list` output.
	pub systems: &'static [&'static str],
	pub blob: &'static [u8],
	/// Logo pixels across and down.
	pub width: u8,
	pub height: u8,
	/// The ASCII form's columns and rows; both 0 when the logo has none.
	pub ascii_width: u8,
	pub ascii_rows: u8,
	pub palette_len: u8,
	/// `PIXELS`, always present.
	pub pixels: Section,
	/// `PIXELS_LOW`, for 16 colours, mono and the cells form.
	pub low: Option<Section>,
	/// `ASCII`.
	pub ascii: Option<Section>,
}

impl LogoEntry {
	/// The payload of a section.
	pub fn payload(&self, section: Section) -> &'static [u8] {
		let start = usize::from(section.offset);
		self.blob.get(start..start + usize::from(section.len)).unwrap_or(&[])
	}
}

/// The logo called `name`, ignoring ASCII case.
pub fn find(name: &str) -> Option<&'static LogoEntry> {
	LOGOS.iter().find(|logo| logo.name.eq_ignore_ascii_case(name))
}

/// The tone with this id (1 to 15).
pub fn tone(id: u8) -> Option<&'static Tone> {
	TONES.iter().find(|tone| tone.id == id)
}

/// The tone whose letter is `letter` in an ASCII tone row.
pub fn tone_by_letter(letter: u8) -> Option<&'static Tone> {
	TONES.iter().find(|tone| tone.letter == letter)
}

/// The accent tone of the title rule for an architecture name (`x86`, `x86_64`, `arm`, `aarch64`, `mips`, `riscv64`,
/// `powerpc64`), or the `other` accent.
pub fn arch_accent(architecture: &str) -> Option<&'static Tone> {
	let id = ARCH_ACCENTS
		.iter()
		.find(|(name, _)| *name == architecture)
		.or_else(|| ARCH_ACCENTS.iter().find(|(name, _)| *name == "other"))?
		.1;
	tone(id)
}

/// The default logo's name for a platform (`dos`, `win16`, `win32`, `linux`, `freebsd`, `macos`, `desk`, `other`): the
/// manifest's default when that logo has been drawn, else [`FALLBACK_LOGO`].
pub fn default_logo(platform: &str) -> &'static str {
	let wanted = DEFAULTS
		.iter()
		.find(|(name, _)| *name == platform)
		.or_else(|| DEFAULTS.iter().find(|(name, _)| *name == "other"));
	match wanted {
		Some((_, logo)) if find(logo).is_some() => logo,
		_ => FALLBACK_LOGO,
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn fallback_logo_is_afterglow() {
		assert_eq!(FALLBACK_LOGO, "afterglow");
		assert!(find(FALLBACK_LOGO).is_some());
	}

	#[test]
	fn every_blob_agrees_with_its_index_entry() {
		assert!(!LOGOS.is_empty());
		for logo in LOGOS {
			let blob = logo.blob;
			assert_eq!(&blob[..4], b"AFL1", "{}", logo.name);
			assert_eq!(blob[4], logo.width);
			assert_eq!(blob[5], logo.height);
			assert_eq!(blob[6], logo.ascii_width);
			assert_eq!(blob[7], logo.ascii_rows);
			assert_eq!(blob[8], logo.palette_len);
			assert!(blob.len() <= 700, "{} is over its budget", logo.name);
			for (section, kind) in [(Some(logo.pixels), 1u8), (logo.low, 2), (logo.ascii, 3)] {
				if let Some(section) = section {
					let header = usize::from(section.offset) - 3;
					assert_eq!(blob[header], kind, "{}", logo.name);
					assert_eq!(u16::from_le_bytes([blob[header + 1], blob[header + 2]]), section.len);
					assert_eq!(logo.payload(section).len(), usize::from(section.len));
				}
			}
			assert_eq!(logo.ascii.is_some(), logo.ascii_width > 0);
		}
	}

	#[test]
	fn total_size_is_within_budget() {
		assert!(LOGOS.iter().map(|logo| logo.blob.len()).sum::<usize>() <= 6144);
	}

	#[test]
	fn tones_are_ordered_and_unique() {
		for (position, tone) in TONES.iter().enumerate() {
			assert_eq!(usize::from(tone.id), position + 1);
			assert_eq!(tone_by_letter(tone.letter).map(|found| found.id), Some(tone.id));
			assert_eq!(tone.console16.is_some(), tone.ansi16.is_some());
		}
	}

	#[test]
	fn the_tones_every_logo_names_exist() {
		for logo in LOGOS {
			for &id in &logo.blob[9..9 + usize::from(logo.palette_len)] {
				assert!(tone(id).is_some());
			}
		}
	}

	#[test]
	fn find_ignores_case_and_defaults_fall_back() {
		assert_eq!(find("WIN32").map(|logo| logo.name), Some("win32"));
		assert!(find("nonesuch").is_none());
		assert!(find(default_logo("nonesuch")).is_some());
		assert!(find(default_logo("win32")).is_some());
	}

	#[test]
	fn arch_accents_resolve() {
		assert_eq!(arch_accent("x86_64").map(|tone| tone.name), Some("gold"));
		assert_eq!(arch_accent("sparc").map(|tone| tone.name), Some("slate"));
	}

	#[test]
	fn reactos_console_indexes_are_held() {
		let held = [
			("gold", 14),
			("orange", 6),
			("coral", 12),
			("rose", 4),
			("lilac", 13),
			("violet", 5),
			("periwinkle", 1),
			("slate", 8),
		];
		for (name, index) in held {
			let tone = TONES.iter().find(|tone| tone.name == name).unwrap();
			assert_eq!(tone.console16, Some(index), "{name}");
		}
	}
}
